tool_input.command:
# Remove junctions first (link only), then dirs
$targets = @(
  @{ dir='D:\repository\worktrees\szfc-v3-wt-bug6070-zhi2'; links=@('node_modules') },
  @{ dir='D:\repository\worktrees\szfc-v3-wt-bug6070';      links=@('node_modules') },
  @{ dir='D:\repository\worktrees\dist6070';               links=@('node_modules','zhi2-web-admin') }
)
foreach($t in $targets){
  foreach($l in $t.links){
    $p = Join-Path $t.dir $l
    if(Test-Path $p){ (Get-Item $p -Force).Delete(); echo "removed junction: $p" }
  }
}
echo '=== after junction removal ==='
foreach($t in $targets){ if(Test-Path $t.dir){ Get-ChildItem $t.dir -Force | Select-Object Mode,Name,LinkType | Format-Table -AutoSize | Out-String } }
